#' Categorize Continuous Variables
#'
#' 
#' @param data .
#' @param var .
#' @param method .
#' @param nbins .
#' @param breaks .
#' @param sdmult .
#' @param seed .
#' @param labels .
#' @param customlabels .
#' @param newvarname .
#' @param excludeoutofrange .
#' @param includelowest .
#' @param rightclosed .
#' @param ordered .
#' @param excl .
#' @param showcode .
#' @param showplot .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$freqTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$breakpointsTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$preview} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$interpretation} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$rcode} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$addtodata} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
pycategorize <- function(
    data,
    var = NULL,
    method = "quantile",
    nbins = 4,
    breaks = "",
    sdmult = 1,
    seed = 20240101,
    labels = "auto",
    customlabels = "",
    newvarname = "",
    excludeoutofrange = FALSE,
    includelowest = TRUE,
    rightclosed = TRUE,
    ordered = TRUE,
    excl = TRUE,
    showcode = TRUE,
    showplot = TRUE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pycategorize requires jmvcore to be installed (restart may be required)")

    if ( ! missing(var)) var <- jmvcore::resolveQuo(jmvcore::enquo(var))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(var), var, NULL))


    options <- pycategorizeOptions$new(
        var = var,
        method = method,
        nbins = nbins,
        breaks = breaks,
        sdmult = sdmult,
        seed = seed,
        labels = labels,
        customlabels = customlabels,
        newvarname = newvarname,
        excludeoutofrange = excludeoutofrange,
        includelowest = includelowest,
        rightclosed = rightclosed,
        ordered = ordered,
        excl = excl,
        showcode = showcode,
        showplot = showplot,
        showConsole = showConsole)

    analysis <- pycategorizeClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

